            'நீங்கள் உறுதிப்படுத்தி, கடவுச்சொல்லை மீண்டும் உள்ளிடுவீர்கள், பின் '
            'உங்கள் ஆவணங்கள், கோப்புகள் மற்றும் சுயவிவரம் நிரந்தரமாக '
            'நீக்கப்படும்.',
